const body = $json.body || {};
const nombre = (body.nombre || '').toString().trim();
const asiste = body.asiste === true || body.asiste === 'true' || body.asiste === 'si';
const acompanantes = asiste ? Math.max(0, parseInt(body.acompanantes, 10) || 0) : 0;
const nombresAcompanantes = asiste && Array.isArray(body.nombres_acompanantes)
  ? body.nombres_acompanantes.map(n => String(n).trim()).filter(Boolean)
  : [];

const entry = {
  timestamp: new Date().toISOString(),
  nombre,
  asiste,
  acompanantes,
  nombres_acompanantes: nombresAcompanantes
};

return { json: { line: JSON.stringify(entry) + '\n' } };

const body = $json.body || {};
const nombre_persona = (body.nombre_persona || '').toString().trim();
const tipos = Array.isArray(body.tipos) ? body.tipos.map(t => String(t).trim()).filter(Boolean) : [];
const detalle = (body.detalle || '').toString().trim();

const entry = {
  timestamp: new Date().toISOString(),
  nombre_persona,
  tipos,
  detalle
};

return { json: { line: JSON.stringify(entry) + '\n' } };

function decodeBinaryText(nodeName) {
  try {
    const item = $(nodeName).item;
    if (!item || !item.binary || !item.binary.data) return '';
    return Buffer.from(item.binary.data.data, 'base64').toString('utf-8');
  } catch (e) {
    return '';
  }
}

function parseJsonl(text) {
  return text.split('\n').map(l => l.trim()).filter(Boolean).map(l => {
    try { return JSON.parse(l); } catch (e) { return null; }
  }).filter(Boolean);
}

function escapeHtml(str) {
  return String(str).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

const rsvp = parseJsonl(decodeBinaryText('Leer RSVP'));
const alergenos = parseJsonl(decodeBinaryText('Leer Alergias'));

const rsvpRows = rsvp.map(r => `
  <tr>
    <td>${escapeHtml(r.timestamp || '')}</td>
    <td>${escapeHtml(r.nombre || '')}</td>
    <td>${r.asiste ? 'Sí' : 'No'}</td>
    <td>${escapeHtml(r.acompanantes ?? 0)}</td>
    <td>${escapeHtml((r.nombres_acompanantes || []).join(', '))}</td>
  </tr>`).join('');

const alergenosRows = alergenos.map(a => `
  <tr>
    <td>${escapeHtml(a.timestamp || '')}</td>
    <td>${escapeHtml(a.nombre_persona || '')}</td>
    <td>${escapeHtml((a.tipos || []).join(', '))}</td>
    <td>${escapeHtml(a.detalle || '')}</td>
  </tr>`).join('');

const html = `<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<title>Dashboard · Boda Gloria y José</title>
<style>
  body { font-family: Arial, sans-serif; background: #ebe6da; color: #231f1a; padding: 2rem; }
  h1 { font-family: Georgia, serif; color: #1a382b; }
  h2 { color: #9e773b; margin-top: 2.5rem; }
  table { width: 100%; border-collapse: collapse; background: #fbf9f4; border-radius: 10px; overflow: hidden; }
  th, td { padding: 0.6rem 0.9rem; border-bottom: 1px solid rgba(201,160,99,0.35); text-align: left; font-size: 0.9rem; }
  th { background: #1a382b; color: #e2c290; text-transform: uppercase; font-size: 0.75rem; letter-spacing: 0.05em; }
  tr:last-child td { border-bottom: none; }
</style>
</head>
<body>
  <h1>Gloria &amp; José — Dashboard</h1>

  <h2>Confirmaciones de asistencia (${rsvp.length})</h2>
  <table>
    <thead><tr><th>Fecha</th><th>Nombre</th><th>Asiste</th><th>Acompañantes</th><th>Nombres acompañantes</th></tr></thead>
    <tbody>${rsvpRows || '<tr><td colspan="5">Sin confirmaciones todavía.</td></tr>'}</tbody>
  </table>

  <h2>Alergias e intolerancias (${alergenos.length})</h2>
  <table>
    <thead><tr><th>Fecha</th><th>Persona</th><th>Tipos</th><th>Detalle</th></tr></thead>
    <tbody>${alergenosRows || '<tr><td colspan="4">Sin avisos todavía.</td></tr>'}</tbody>
  </table>
</body>
</html>`;

return [{ json: { html } }];
